FLValue ufl_str_starts_with(FLValue s, FLValue prefix) {
    if (s.tag != FL_STRING || prefix.tag != FL_STRING) return fl_bool(0);
    const char* src = ((FLString*)s.obj)->data;
    const char* pre = ((FLString*)prefix.obj)->data;
    size_t plen = strlen(pre);
    return fl_bool(strncmp(src, pre, plen) == 0);
}
